/*! \brief Processor ends up here if an interrupt occurs and the application has not defined its handler.
    \note  In a DEBUG build the debugger is notified, then the CPU stops in a busy loop.
*/
void Default_Handler(void) __attribute__ ((weak, used));

void Default_Handler(void)
{
#if defined(DEBUG)
    __asm volatile ("bkpt 0");
#endif
    for (;;)
    {
        // nothing to do
    }
}

